-- Alex, 2026-11-27 (docs/batch-2026-11-28-report-fixes.md). The 23 photos the old photo check sent
-- back, which review found to be good listing photos and the confirm step added in PR 202 passes
-- (docs/photo-check-tuning-2026-11-27.md), go back on their listings. Each photo passes as the
-- admin's Use anyway would, with an audit row, and its puppy's last photo date and reminder stage
-- move as lib/inactivity.js photoPassedStmts moves them. None of the 23 puppies is offline or on
-- a hold, read from production at 2026-11-28T00:49:23Z, so that function's other two branches do not apply.
-- Generated by a script from the production rows. Safe to run twice: every write is guarded on
-- the photo still being sent back, and the publish marker comes first, guarded the same way.
UPDATE site_state SET dirty = 1, dirty_since = COALESCE(dirty_since, '2026-11-28T00:49:23Z'), generation = generation + 1
  WHERE id = 1 AND EXISTS (SELECT 1 FROM photos WHERE quality = 'sent_back' AND id IN ('01M6WFXZNXBV457KD4QQZWRWNX','01M740BN3B46Q8PZX00XWZMNTB','01M740G83P34NKF3NXT4BG8PE3','01M740HA7CNTVKBJS1W5P0FWD0','01M740HE4EJPSFKMDHKJJ74EDH','01M76F8KQAJBY1PVP2CEA4R7VN','01M783PTPV2NV30YRDEFDBFYHQ','01M78B7DZCN2TZA36M9RFFD11D','01M78B7Z37CHA9QDA12QETQ5EJ','01M7BCM297QG7WM31SBNV7NK1V','01M7BCX3K3K3BSQZX8TB7JKXXC','01M7BCXTD4P5298K3MV7SNX4TW','01M7D7JZACFD2M6MH916ZE878Y','01M7K7A9AEENMJ9WSVJTW6ZEWD','01M7QNJFRT0VHV6PGPA1NCPD7F','01M7TDJ6GSXS0XSKY2PKGAN7BM','01M7TDJCYD48A4QAJQFTDW9MSV','01M7TDKRM5H69WAR6Y6GTABXW2','01M85HMPR9DM8BWJ3X3XWP35ZX','01M8EYW4GJAD9A5SXF5GCHMMEA','01M8EYW9S6AB0SNZB7EWSW1F0B','01M8EYWGWCSW0788JZQW9X5R3Z','01M8EYWQJ9KGX19G4J0V7SZ5WS'));
